#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

i128 abs128(i128 x) {
    return x < 0 ? -x : x;
}

i128 gcd128(i128 a, i128 b) {
    a = abs128(a);
    b = abs128(b);
    while (b != 0) {
        i128 r = a % b;
        a = b;
        b = r;
    }
    return a;
}

i128 floorDiv(i128 a, i128 b) {
    i128 q = a / b;
    i128 r = a % b;
    if (r < 0) --q;
    return q;
}

void print128(i128 x) {
    if (x == 0) {
        cout << '0';
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 xInput, yInput, n;
    cin >> xInput >> yInput >> n;

    i128 x = xInput;
    i128 y = yInput;

    if (y < 0) {
        x = -x;
        y = -y;
    }

    i128 bestP = 0;
    i128 bestQ = 1;
    i128 bestError = 0;
    bool found = false;

    for (int64 denominator = 1; denominator <= n; ++denominator) {
        i128 q = denominator;
        i128 value = x * q;
        i128 p = floorDiv(value, y);
        i128 remainder = value - p * y;

        if (remainder * 2 >= y)
            ++p;

        i128 g = gcd128(p, q);
        i128 reducedP = p / g;
        i128 reducedQ = q / g;
        i128 error = abs128(reducedP * y - x * reducedQ);

        if (!found ||
            error * bestQ < bestError * reducedQ ||
            (error * bestQ == bestError * reducedQ &&
             reducedQ < bestQ)) {
            bestP = reducedP;
            bestQ = reducedQ;
            bestError = error;
            found = true;
        }
    }

    print128(bestP);
    cout << '/';
    print128(bestQ);
    cout << '\n';

    return 0;
}

