using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, y, n;
    cin >> x >> y >> n;

    const cpp_int X = x;
    const cpp_int Y = y;

    cpp_int bestNumerator;
    long long bestDenominator = 1;
    bool initialized = false;

    for (long long denominator = 1; denominator <= n; ++denominator) {
        cpp_int product = X * denominator;
        cpp_int lower = product / Y;
        cpp_int remainder = product % Y;
        cpp_int upper = lower + (remainder != 0);

        cpp_int numerator =
            (remainder * 2 < Y) ? lower : upper;

        long long remainderMod =
            (numerator % denominator).convert_to<long long>();
        long long g = std::gcd(denominator, remainderMod);

        numerator /= g;
        long long reducedDenominator = denominator / g;

        if (!initialized) {
            bestNumerator = numerator;
            bestDenominator = reducedDenominator;
            initialized = true;
            continue;
        }

        cpp_int currentError =
            numerator * Y - X * reducedDenominator;
        cpp_int bestError =
            bestNumerator * Y - X * bestDenominator;

        if (currentError < 0) currentError = -currentError;
        if (bestError < 0) bestError = -bestError;

        cpp_int lhs = currentError * bestDenominator;
        cpp_int rhs = bestError * reducedDenominator;

        if (lhs < rhs ||
            (lhs == rhs &&
             (reducedDenominator < bestDenominator ||
              (reducedDenominator == bestDenominator &&
               numerator < bestNumerator)))) {
            bestNumerator = numerator;
            bestDenominator = reducedDenominator;
        }
    }

    cout << bestNumerator << '/' << bestDenominator << '\n';
    return 0;
}

